package json_test

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"flag"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/isaquesb/go-event-bus"
	eventjson "github.com/isaquesb/go-event-bus/json"
	"go.opentelemetry.io/otel/baggage"
	"go.opentelemetry.io/otel/trace"
)

// compatUpdate rewrites the golden files. The v030_*.json fixtures are real
// v0.3.0 bytes and are never regenerated by any test.
var compatUpdate = flag.Bool("update", false, "rewrite golden files")

const (
	compatTraceHex = "0102030405060708090a0b0c0d0e0f10"
	compatSpanHex  = "0102030405060708"
	compatTS       = "2026-10-13T15:32:18.140707127Z"
	compatRootID   = "0192f3a0-0000-7000-8000-000000000001"
	compatChildID  = "0192f3a0-0000-7000-8000-000000000002"
)

// compatLegacyEnvelope is a frozen copy of the v0.3.0 Envelope struct.
type compatLegacyEnvelope struct {
	Name      string          `json:"name"`
	Version   int             `json:"version"`
	Timestamp time.Time       `json:"ts"`
	TraceID   string          `json:"trace_id,omitempty"`
	SpanID    string          `json:"span_id,omitempty"`
	Payload   json.RawMessage `json:"payload"`
}

// compatLegacyDecode replicates the v0.3.0 Registry.Decode for a registry that
// knows user.created v1 only: unmarshal the legacy envelope, restore the trace
// ids as a sampled remote span context, and unmarshal the payload.
func compatLegacyDecode(t *testing.T, data []byte) (context.Context, *UserCreatedV1, compatLegacyEnvelope) {
	t.Helper()

	var env compatLegacyEnvelope
	if err := json.Unmarshal(data, &env); err != nil {
		t.Fatalf("legacy decoder cannot read the envelope: %v", err)
	}

	ctx := context.Background()
	if env.TraceID != "" {
		tid, tErr := trace.TraceIDFromHex(env.TraceID)
		sid, sErr := trace.SpanIDFromHex(env.SpanID)
		if tErr == nil && sErr == nil {
			ctx = trace.ContextWithSpanContext(ctx, trace.NewSpanContext(trace.SpanContextConfig{
				TraceID:    tid,
				SpanID:     sid,
				TraceFlags: trace.FlagsSampled,
				Remote:     true,
			}))
		}
	}

	evt := &UserCreatedV1{}
	if err := json.Unmarshal(env.Payload, evt); err != nil {
		t.Fatalf("legacy decoder cannot read the payload: %v", err)
	}

	return ctx, evt, env
}

func compatRegistry() *eventjson.Registry {
	reg := eventjson.NewRegistry()
	reg.Register("user.created", func() event.Event { return &UserCreatedV1{} }, 1)
	return reg
}

func compatReadFile(t *testing.T, path string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.FromSlash(path))
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	return data
}

func compatTimestamp(t *testing.T) time.Time {
	t.Helper()
	ts, err := time.Parse(time.RFC3339Nano, compatTS)
	if err != nil {
		t.Fatalf("parse timestamp: %v", err)
	}
	return ts
}

func compatCheckUser(t *testing.T, evt event.Event) {
	t.Helper()
	got, ok := evt.(*UserCreatedV1)
	if !ok {
		t.Fatalf("expected *UserCreatedV1, got %T", evt)
	}
	if got.UserID != "user-123" || got.UserName != "John" {
		t.Errorf("decoded %+v, want user-123 / John", got)
	}
}

func TestCompat_OldToNew_Traced(t *testing.T) {
	ctx, evt, err := compatRegistry().Decode(context.Background(), compatReadFile(t, "testdata/v030_traced.json"))
	if err != nil {
		t.Fatalf("decode error: %v", err)
	}
	compatCheckUser(t, evt)

	md, ok := event.MetadataFromContext(ctx)
	if !ok {
		t.Fatal("expected Metadata in the decoded ctx")
	}
	if md.ID != "" {
		t.Errorf("Metadata.ID = %q, want empty for a v0.3.0 envelope", md.ID)
	}
	if md.Name != "user.created" || md.Version != 1 {
		t.Errorf("Metadata name/version = %q v%d, want user.created v1", md.Name, md.Version)
	}
	if !md.Timestamp.Equal(compatTimestamp(t)) {
		t.Errorf("Metadata.Timestamp = %s, want %s", md.Timestamp, compatTS)
	}

	sc := trace.SpanContextFromContext(ctx)
	if !sc.IsValid() {
		t.Fatal("expected a valid span context restored from the legacy ids")
	}
	if !sc.IsRemote() {
		t.Error("restored span context must be remote")
	}
	if !sc.IsSampled() {
		t.Error("restored span context must be sampled (D-16)")
	}
	if sc.TraceID().String() != compatTraceHex || sc.SpanID().String() != compatSpanHex {
		t.Errorf("span context = %s/%s, want %s/%s", sc.TraceID(), sc.SpanID(), compatTraceHex, compatSpanHex)
	}
}

func TestCompat_OldToNew_Untraced(t *testing.T) {
	ctx, evt, err := compatRegistry().Decode(context.Background(), compatReadFile(t, "testdata/v030_untraced.json"))
	if err != nil {
		t.Fatalf("decode error: %v", err)
	}
	compatCheckUser(t, evt)

	if sc := trace.SpanContextFromContext(ctx); sc.IsValid() {
		t.Errorf("an untraced envelope must not produce a span context, got %v", sc)
	}

	md, ok := event.MetadataFromContext(ctx)
	if !ok || md.ID != "" {
		t.Errorf("Metadata = %+v ok=%v, want present with empty ID", md, ok)
	}
}

func TestCompat_OldToNew_Version0(t *testing.T) {
	ctx, evt, err := compatRegistry().Decode(context.Background(), compatReadFile(t, "testdata/v030_version0.json"))
	if err != nil {
		t.Fatalf("decode error: %v", err)
	}
	compatCheckUser(t, evt)

	md, ok := event.MetadataFromContext(ctx)
	if !ok {
		t.Fatal("expected Metadata in the decoded ctx")
	}
	if md.Version != 1 {
		t.Errorf("Metadata.Version = %d, want 1 (D-18)", md.Version)
	}
}

func TestCompat_Fixtures_TypedErrors(t *testing.T) {
	tests := []struct {
		file string
		want error
	}{
		{"testdata/legacy_dlq_record.json", event.ErrMalformedEnvelope},
		{"testdata/unknown_event.json", event.ErrUnknownEvent},
		{"testdata/future_version.json", event.ErrUnknownVersion},
	}

	for _, tc := range tests {
		t.Run(filepath.Base(tc.file), func(t *testing.T) {
			_, evt, err := compatRegistry().Decode(context.Background(), compatReadFile(t, tc.file))
			if err == nil {
				t.Fatalf("expected an error, got %T", evt)
			}
			if !errors.Is(err, tc.want) {
				t.Errorf("errors.Is(%v, %v) = false", err, tc.want)
			}
			var de *event.DecodeError
			if !errors.As(err, &de) {
				t.Errorf("expected *event.DecodeError, got %T", err)
			}
		})
	}
}

// compatGoldenFull builds the full envelope: lineage, a user header, and a
// sampled span with tracestate and baggage.
func compatGoldenFull(t *testing.T) []byte {
	t.Helper()

	tid, err := trace.TraceIDFromHex(compatTraceHex)
	if err != nil {
		t.Fatal(err)
	}
	sid, err := trace.SpanIDFromHex(compatSpanHex)
	if err != nil {
		t.Fatal(err)
	}
	ts, err := trace.ParseTraceState("vendor=abc")
	if err != nil {
		t.Fatal(err)
	}
	member, err := baggage.NewMember("k", "v")
	if err != nil {
		t.Fatal(err)
	}
	bag, err := baggage.New(member)
	if err != nil {
		t.Fatal(err)
	}

	ctx := trace.ContextWithSpanContext(context.Background(), trace.NewSpanContext(trace.SpanContextConfig{
		TraceID:    tid,
		SpanID:     sid,
		TraceFlags: trace.FlagsSampled,
		TraceState: ts,
	}))
	ctx = baggage.ContextWithBaggage(ctx, bag)

	data, err := compatRegistry().EncodeWith(ctx, &UserCreatedV1{UserID: "user-123", UserName: "John"}, event.Metadata{
		ID:            compatChildID,
		CorrelationID: compatRootID,
		CausationID:   compatRootID,
		Timestamp:     compatTimestamp(t),
		Headers:       map[string]string{"tenant": "acme"},
	})
	if err != nil {
		t.Fatalf("encode full: %v", err)
	}
	return data
}

// compatGoldenMinimal builds a root envelope: no headers, no span.
func compatGoldenMinimal(t *testing.T) []byte {
	t.Helper()

	data, err := compatRegistry().EncodeWith(context.Background(), &UserCreatedV1{UserID: "user-123", UserName: "John"}, event.Metadata{
		ID:            compatRootID,
		CorrelationID: compatRootID,
		Timestamp:     compatTimestamp(t),
	})
	if err != nil {
		t.Fatalf("encode minimal: %v", err)
	}
	return data
}

func TestGolden(t *testing.T) {
	tests := []struct {
		path string
		make func(*testing.T) []byte
	}{
		{"testdata/golden/new_full.golden.json", compatGoldenFull},
		{"testdata/golden/new_minimal.golden.json", compatGoldenMinimal},
	}

	for _, tc := range tests {
		t.Run(filepath.Base(tc.path), func(t *testing.T) {
			got := tc.make(t)

			if *compatUpdate {
				if err := os.WriteFile(filepath.FromSlash(tc.path), got, 0o644); err != nil {
					t.Fatalf("write golden: %v", err)
				}
			}

			want := compatReadFile(t, tc.path)
			if !bytes.Equal(got, want) {
				t.Errorf("golden mismatch for %s (rerun with -update to rewrite)\n got: %s\nwant: %s", tc.path, got, want)
			}
		})
	}
}

func TestCompat_NewToOld(t *testing.T) {
	ts := compatTimestamp(t)

	tests := []struct {
		path      string
		wantTrace bool
	}{
		{"testdata/golden/new_full.golden.json", true},
		{"testdata/golden/new_minimal.golden.json", false},
	}

	for _, tc := range tests {
		t.Run(filepath.Base(tc.path), func(t *testing.T) {
			ctx, evt, env := compatLegacyDecode(t, compatReadFile(t, tc.path))

			if evt.UserID != "user-123" || evt.UserName != "John" {
				t.Errorf("legacy decoder read %+v, want user-123 / John", evt)
			}
			if env.Name != "user.created" || env.Version != 1 {
				t.Errorf("legacy name/version = %q v%d, want user.created v1", env.Name, env.Version)
			}
			if !env.Timestamp.Equal(ts) {
				t.Errorf("legacy timestamp = %s, want %s", env.Timestamp, compatTS)
			}

			sc := trace.SpanContextFromContext(ctx)
			if !tc.wantTrace {
				if env.TraceID != "" || env.SpanID != "" || sc.IsValid() {
					t.Errorf("minimal golden must carry no legacy trace ids, got %q/%q", env.TraceID, env.SpanID)
				}
				return
			}

			// Dual write (D-03): the legacy fields equal the span ids.
			if env.TraceID != compatTraceHex || env.SpanID != compatSpanHex {
				t.Errorf("legacy trace ids = %q/%q, want %s/%s", env.TraceID, env.SpanID, compatTraceHex, compatSpanHex)
			}
			if !sc.IsValid() || sc.TraceID().String() != compatTraceHex || sc.SpanID().String() != compatSpanHex {
				t.Errorf("legacy decoder span context = %v", sc)
			}
		})
	}
}
